sp_widget.client_script:
api.controller = function($scope, $rootScope, $element, $timeout, $interval, $window) {
    /* Fun on PDI - Crossword widget (client controller) */
    var c = this;

    // Game masters signed in at /fun are sent to the console (decided on the server).
    c.redirecting = !!c.data.redirectTo;
    if (c.redirecting) {
        $window.location.replace(c.data.redirectTo);
        return;
    }

    var AUTOSAVE_DELAY_MS = 1500;   // save shortly after typing stops
    var AUTOSAVE_EVERY_MS = 20000;  // safety net in case a save failed
    var WAIT_POLL_MS = 5000;        // how often a waiting team checks whether the game has started
    var STATUS_POLL_MS = 10000;     // while playing: notices an End game from the console

    c.game = c.data.game || { ok: false, message: 'Could not load the crossword. Please refresh the page.' };
    c.tagline = 'Hunt the instance. Crack the clue.';   // shown under the game name
    c.howtoOpen = true;                                  // 'How to play' starts open
    c.cells = [];
    c.cellMap = {};
    c.words = [];
    c.across = [];
    c.down = [];
    c.sel = null;               // { pos: 'r_c' (display position), dir: 'across' | 'down' }
    c.locked = false;
    c.dirty = false;
    c.saving = false;
    c.submitting = false;
    c.confirmOpen = false;
    c.saveText = '';
    c.timerText = '';
    c.remaining = 0;
    c.resultText = '';
    c.resultKind = '';
    c.errorText = '';

    var endAt = 0;
    var tickTimer = null;
    var autosaveTimer = null;
    var autosaveLoop = null;
    var timeUpSent = false;
    var waitPoll = null;
    var statusPoll = null;
    var statusBusy = false;
    var waitBusy = false;
    var initialised = false;

    // First-login team setup
    c.reg = { name: '', members: ['', ''], saving: false, error: '' };


    /* ---------- crisp board at any display scaling ----------
     * Squares are sized to a whole number of screen pixels and lines are exactly
     * 1 screen pixel (2 on high-density screens), so every grid line has the same
     * thickness at 100%, 125%, 150% and 200% Windows/browser scaling. */
    var BOARD_MAX_CELL = 35;   // CSS px at 100%
    var BOARD_SIDE_SPACE = 64; // space the page needs around the board on small screens
    c.cellPx = BOARD_MAX_CELL;
    c.linePx = 1;
    c.padPx = 10;

    function sizeBoard() {
        var cols = c.cols;
        if (!cols) return;
        var dpr = $window.devicePixelRatio || 1;
        var target = Math.min(BOARD_MAX_CELL, ($window.innerWidth - BOARD_SIDE_SPACE) / cols);
        c.cellPx = Math.max(12, Math.floor(target * dpr)) / dpr;
        c.linePx = Math.max(1, Math.round(dpr)) / dpr;
        c.padPx = Math.round(10 * dpr) / dpr;
    }

    c.boardStyle = function() {
        var px = function(v) { return (Math.round(v * 10000) / 10000) + 'px'; };
        var cell = c.cellPx, line = c.linePx, pad = c.padPx;
        // Everything is pre-computed here: the portal's SCSS compiler mangles calc() with
        // CSS variable fallbacks, so the CSS only reads these plain values.
        return '--cols: ' + c.cols +
            '; --cell: ' + px(cell) +
            '; --overlap: -' + px(line) +           // frame reaches one line into the next square
            '; --line: ' + px(line) +
            '; --pad: ' + px(pad) +
            '; --pad-end: ' + px(pad + line) +
            '; --num: ' + px(cell * 0.27) +
            '; --letter: ' + px(cell * 0.56);
    };

    var onResize = function() { $scope.$applyAsync(sizeBoard); };
    angular.element($window).on('resize', onResize);
    $scope.$on('$destroy', function() { angular.element($window).off('resize', onResize); });

    if (c.game.ok && c.game.waiting) startWaiting();
    if (c.game.ok && !c.game.needsRegistration && !c.game.waiting && !c.game.ended) init();
    if (c.game.ok && c.game.needsRegistration) {
        $timeout(function() {
            var el = $element[0].querySelector('#fun-reg-name');
            if (el) el.focus();
        });
    }

    /* ---------------- team setup (first login) ---------------- */

    c.addMember = function() {
        if (c.reg.members.length >= 8) return;
        c.reg.members.push('');
        var idx = c.reg.members.length - 1;
        $timeout(function() {
            var el = $element[0].querySelector('#fun-member-' + idx);
            if (el) el.focus();
        });
    };

    c.removeMember = function(i) {
        if (c.reg.members.length > 1) c.reg.members.splice(i, 1);
    };

    c.registerTeam = function() {
        var name = String(c.reg.name || '').replace(/\s+/g, ' ').trim();
        var members = c.reg.members
            .map(function(m) { return String(m || '').replace(/\s+/g, ' ').trim(); })
            .filter(function(m) { return m; });

        if (name.length < 2) { c.reg.error = 'Enter a team name of at least 2 characters.'; return; }
        if (!members.length) { c.reg.error = 'Add at least one team member.'; return; }

        c.reg.saving = true;
        c.reg.error = '';
        c.server.get({ action: 'register', teamName: name, members: members }).then(function(resp) {
            var res = resp.data.result;
            if (!res || !res.ok) {
                c.reg.saving = false;
                c.reg.error = (res && res.message) || 'Could not save your team. Please try again.';
                return;
            }
            $rootScope.$broadcast('fun.teamRegistered', res.team); // updates the header
            c.server.get({ action: 'refresh' }).then(function(r2) {
                c.reg.saving = false;
                var g = r2.data.result;
                if (g && g.ok && g.waiting) {
                    c.game = g;
                    startWaiting();
                } else if (g && g.ok && g.ended) {
                    c.game = g;
                } else if (g && g.ok && !g.needsRegistration) {
                    c.game = g;
                    init();
                } else {
                    c.reg.error = (g && g.message) || 'Your team was saved. Please refresh the page to start.';
                }
            });
        }, function() {
            c.reg.saving = false;
            c.reg.error = 'Could not reach the server. Please try again.';
        });
    };

    /* ---------------- waiting for the game to start ---------------- */

    function startWaiting() {
        if (waitPoll) return;
        waitPoll = $interval(function() {
            if (waitBusy) return;
            waitBusy = true;
            c.server.get({ action: 'refresh' }).then(function(resp) {
                waitBusy = false;
                var g = resp.data.result;
                if (g && g.ok && g.ended) {
                    $interval.cancel(waitPoll);
                    waitPoll = null;
                    c.game = g;
                } else if (g && g.ok && !g.waiting && !g.needsRegistration) {
                    $interval.cancel(waitPoll);
                    waitPoll = null;
                    c.game = g;
                    init();
                }
            }, function() { waitBusy = false; });
        }, WAIT_POLL_MS);
    }

    /* ---------------- setup ---------------- */

    function init() {
        if (initialised) return;
        initialised = true;
        var g = c.game;
        c.rows = g.puzzle.rows;
        c.cols = g.puzzle.cols;

        // Show only the area the words use, plus a 1-square margin, so there is no empty
        // space above or below. Display positions are shifted; saved keys keep the
        // original row_col from Puzzle Word.
        var minR = Infinity, maxR = -Infinity, minC = Infinity, maxC = -Infinity;
        g.words.forEach(function(w) {
            var endR = w.direction == 'down' ? w.row + w.length - 1 : w.row;
            var endC = w.direction == 'across' ? w.col + w.length - 1 : w.col;
            minR = Math.min(minR, w.row); maxR = Math.max(maxR, endR);
            minC = Math.min(minC, w.col); maxC = Math.max(maxC, endC);
        });
        var MARGIN = 1, offR = 0, offC = 0;
        if (g.words.length) {
            c.rows = (maxR - minR + 1) + 2 * MARGIN;
            c.cols = (maxC - minC + 1) + 2 * MARGIN;
            offR = MARGIN - minR;
            offC = MARGIN - minC;
        }

        c.posMap = {};
        for (var r = 0; r < c.rows; r++) {
            for (var col = 0; col < c.cols; col++) {
                var cell = { pos: r + '_' + col, key: null, r: r, c: col, active: false, number: null, letter: '', across: null, down: null };
                c.cells.push(cell);
                c.posMap[cell.pos] = cell;
            }
        }

        g.words.forEach(function(w) {
            w.cells = [];
            for (var i = 0; i < w.length; i++) {
                var or = w.direction == 'across' ? w.row : w.row + i;
                var oc = w.direction == 'across' ? w.col + i : w.col;
                var cell = c.posMap[(or + offR) + '_' + (oc + offC)];
                if (!cell) continue; // outside the grid; validatePuzzle() reports this
                cell.active = true;
                cell.key = or + '_' + oc;
                c.cellMap[cell.key] = cell;
                cell[w.direction] = w;
                w.cells.push(cell);
            }
            var start = c.posMap[(w.row + offR) + '_' + (w.col + offC)];
            if (start) start.number = w.number;
            (w.direction == 'across' ? c.across : c.down).push(w);
        });

        sizeBoard();
        c.words = g.words;
        c.activeCells = c.cells.filter(function(x) { return x.active; });
        c.totalCells = c.activeCells.length;

        applySession(g.session, true);

        if (!c.locked) {
            var first = c.across[0] || c.down[0];
            if (first) select(firstEmptyCell(first), first.direction, false);
            autosaveLoop = $interval(function() { if (c.dirty) save(); }, AUTOSAVE_EVERY_MS);
            statusPoll = $interval(checkStatus, STATUS_POLL_MS);
        }
        tickTimer = $interval(updateTimer, 1000);
        updateTimer();
        // Header shows "Open ServiceNow Platform" only while this team is playing.
        $rootScope.$broadcast('fun.gameState', c.locked ? 'stopped' : 'running');
    }

    /** Applies a session from the server. Letters are only overwritten on first load or once submitted. */
    function applySession(s, initial) {
        if (!s) return;
        if (initial || s.status == 'submitted') {
            var cells = s.cells || {};
            c.activeCells.forEach(function(cell) { cell.letter = cells[cell.key] || ''; });
        }
        if (s.status == 'submitted') {
            lock(s);
        } else {
            endAt = Date.now() + (s.remainingSeconds || 0) * 1000;
        }
    }

    function lock(s) {
        c.locked = true;
        $rootScope.$broadcast('fun.gameState', 'stopped');
        c.sel = null;
        c.confirmOpen = false;
        c.dirty = false;
        c.errorText = '';
        cancelAutosave();
        if (autosaveLoop) { $interval.cancel(autosaveLoop); autosaveLoop = null; }
        if (statusPoll) { $interval.cancel(statusPoll); statusPoll = null; }
        if (s.submitType == 'auto') {
            c.resultKind = 'warn';
            c.resultText = "Time's up! Your crossword was submitted automatically after " + s.timeTakenText + '.';
            c.timerText = '00:00';
        } else if (s.submitType == 'ended') {
            c.resultKind = 'warn';
            c.resultText = 'The game has ended. Your crossword was submitted after ' + s.timeTakenText + '.';
            c.timerText = 'Ended';
        } else {
            c.resultKind = 'ok';
            c.resultText = 'Submitted! You completed the crossword in ' + s.timeTakenText + '.';
            c.timerText = 'Done';
        }
    }

    /** While playing: picks up an End game from the console, and keeps the timer in sync. */
    function checkStatus() {
        if (c.locked || statusBusy || c.submitting) return;
        statusBusy = true;
        c.server.get({ action: 'refresh' }).then(function(resp) {
            statusBusy = false;
            var g = resp.data.result;
            if (!g || !g.ok) return;
            if (g.ended) { lock({ submitType: 'ended', timeTakenText: '' }); c.game = g; return; }
            if (g.session) applySession(g.session, false);
        }, function() { statusBusy = false; });
    }

    /* ---------------- timer ---------------- */

    function updateTimer() {
        if (c.locked) return;
        c.remaining = Math.max(0, Math.ceil((endAt - Date.now()) / 1000));
        c.timerText = formatClock(c.remaining);
        if (c.remaining <= 0 && !timeUpSent) {
            timeUpSent = true;
            doSubmit(true);
        }
    }

    function formatClock(sec) {
        var h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
        var pad = function(n) { return (n < 10 ? '0' : '') + n; };
        return h > 0 ? h + ':' + pad(m) + ':' + pad(s) : pad(m) + ':' + pad(s);
    }

    c.timerClass = function() {
        if (c.locked) return 'is-done';
        if (c.remaining <= 60) return 'is-critical';
        if (c.remaining <= 300) return 'is-low';
        return '';
    };

    /* ---------------- selection ---------------- */

    c.currentWord = function() {
        if (!c.sel) return null;
        var cell = c.posMap[c.sel.pos];
        return cell ? (cell[c.sel.dir] || cell.across || cell.down) : null;
    };

    c.dirLabel = function(dir) { return dir == 'across' ? 'Across' : 'Down'; };

    c.cellClass = function(cell) {
        if (!cell.active) return 'is-block';
        var cls = '';
        var w = c.currentWord();
        if (w && cell[w.direction] === w) cls += ' in-word';
        if (c.sel && c.sel.pos == cell.pos) cls += ' is-active';
        return cls;
    };

    function select(cell, dir, focus) {
        if (!cell || !cell.active) return;
        var d = cell[dir] ? dir : (cell.across ? 'across' : 'down');
        c.sel = { pos: cell.pos, dir: d };
        if (focus !== false) focusCell(cell);
    }

    function focusCell(cell) {
        $timeout(function() {
            var el = $element[0].querySelector('#fun-cell-' + cell.pos);
            if (el) {
                el.focus();
                if (el.setSelectionRange) el.setSelectionRange(0, el.value.length);
            }
        });
    }

    function firstEmptyCell(w) {
        for (var i = 0; i < w.cells.length; i++) if (!w.cells[i].letter) return w.cells[i];
        return w.cells[0];
    }

    c.onCellClick = function(cell) {
        if (c.locked) return;
        if (c.sel && c.sel.pos == cell.pos && cell.across && cell.down) {
            c.sel.dir = c.sel.dir == 'across' ? 'down' : 'across'; // click again to switch direction
            return;
        }
        select(cell, c.sel ? c.sel.dir : 'across', false);
    };

    c.selectWord = function(w) {
        if (c.locked || !w.cells.length) return;
        select(firstEmptyCell(w), w.direction);
    };

    /* ---------------- typing ---------------- */

    function ensureSelected(cell) {
        if (!c.sel || c.sel.pos != cell.pos) select(cell, c.sel ? c.sel.dir : 'across', false);
    }

    c.onKey = function(e, cell) {
        if (c.locked) return;
        ensureSelected(cell);
        var k = e.key;

        if (k && k.length == 1 && /[a-z]/i.test(k) && !e.ctrlKey && !e.metaKey && !e.altKey) {
            e.preventDefault();
            setLetter(cell, k.toUpperCase());
            stepInWord(cell, 1);
            return;
        }

        switch (k) {
            case 'Backspace':
                e.preventDefault();
                if (cell.letter) {
                    setLetter(cell, '');
                } else {
                    var prev = neighbourInWord(cell, -1);
                    if (prev) { setLetter(prev, ''); select(prev, c.sel.dir); }
                }
                return;
            case 'Delete':
                e.preventDefault();
                setLetter(cell, '');
                return;
            case 'ArrowRight': e.preventDefault(); moveLine(cell, 0, 1, 'across'); return;
            case 'ArrowLeft':  e.preventDefault(); moveLine(cell, 0, -1, 'across'); return;
            case 'ArrowDown':  e.preventDefault(); moveLine(cell, 1, 0, 'down'); return;
            case 'ArrowUp':    e.preventDefault(); moveLine(cell, -1, 0, 'down'); return;
            case ' ':
            case 'Spacebar':
                e.preventDefault();
                if (cell.across && cell.down) c.sel.dir = c.sel.dir == 'across' ? 'down' : 'across';
                return;
            case 'Tab':
                e.preventDefault();
                jumpWord(e.shiftKey ? -1 : 1);
                return;
            case 'Enter':
                e.preventDefault();
                if (c.allFilled()) c.openConfirm();
                return;
        }
    };

    /** Fallback for mobile keyboards, which often don't report the key in keydown. */
    c.onInput = function(cell) {
        if (c.locked) return;
        ensureSelected(cell);
        var v = String(cell.letter || '').toUpperCase().replace(/[^A-Z]/g, '');
        cell.letter = v.slice(-1);
        markDirty();
        if (cell.letter) stepInWord(cell, 1);
    };

    function setLetter(cell, v) {
        if (cell.letter !== v) {
            cell.letter = v;
            markDirty();
        }
    }

    function neighbourInWord(cell, delta) {
        var w = c.currentWord();
        if (!w) return null;
        var i = w.cells.indexOf(cell);
        return i < 0 ? null : (w.cells[i + delta] || null);
    }

    function stepInWord(cell, delta) {
        var next = neighbourInWord(cell, delta);
        if (next) select(next, c.sel.dir);
    }

    function moveLine(cell, dr, dc, dir) {
        if (cell[dir] && c.sel.dir != dir) { c.sel.dir = dir; return; } // first press turns, next press moves
        var r = cell.r + dr, col = cell.c + dc;
        while (r >= 0 && r < c.rows && col >= 0 && col < c.cols) {
            var t = c.posMap[r + '_' + col];
            if (t.active) { select(t, t[dir] ? dir : c.sel.dir); return; }
            r += dr; col += dc;
        }
    }

    function jumpWord(delta) {
        var list = c.across.concat(c.down);
        if (!list.length) return;
        var i = list.indexOf(c.currentWord());
        var next = list[(i + delta + list.length) % list.length];
        select(firstEmptyCell(next), next.direction);
    }

    /* ---------------- progress ---------------- */

    c.isWordFilled = function(w) {
        for (var i = 0; i < w.cells.length; i++) if (!w.cells[i].letter) return false;
        return w.cells.length > 0;
    };

    c.wordsFilled = function() {
        return c.words.filter(c.isWordFilled).length;
    };

    c.allFilled = function() {
        for (var i = 0; i < c.activeCells.length; i++) if (!c.activeCells[i].letter) return false;
        return c.activeCells.length > 0;
    };

    function collectCells() {
        var out = {};
        c.activeCells.forEach(function(cell) { if (cell.letter) out[cell.key] = cell.letter; });
        return out;
    }

    /* ---------------- autosave ---------------- */

    function markDirty() {
        c.dirty = true;
        c.saveText = 'Unsaved changes';
        cancelAutosave();
        autosaveTimer = $timeout(save, AUTOSAVE_DELAY_MS);
    }

    function cancelAutosave() {
        if (autosaveTimer) { $timeout.cancel(autosaveTimer); autosaveTimer = null; }
    }

    function save() {
        if (c.locked || c.saving || c.submitting) return;
        c.saving = true;
        c.dirty = false;
        c.saveText = 'Saving…';
        c.server.get({ action: 'save', cells: collectCells() }).then(function(resp) {
            c.saving = false;
            var res = resp.data.result;
            if (!res || !res.ok) {
                c.dirty = true;
                c.saveText = 'Not saved yet, retrying';
                return;
            }
            if (!c.dirty) c.saveText = 'Saved';
            applySession(res.session, false);
        }, function() {
            c.saving = false;
            c.dirty = true;
            c.saveText = 'Offline, retrying';
        });
    }

    /* ---------------- submit ---------------- */

    c.openConfirm = function() {
        if (c.locked || !c.allFilled()) return;
        c.confirmOpen = true;
    };

    c.closeConfirm = function() { c.confirmOpen = false; };

    c.confirmSubmit = function() {
        c.confirmOpen = false;
        doSubmit(false);
    };

    function doSubmit(isTimeUp) {
        if (c.locked || c.submitting) return;
        c.submitting = true;
        c.errorText = '';
        cancelAutosave();

        c.server.get({ action: 'submit', cells: collectCells(), isTimeUp: isTimeUp }).then(function(resp) {
            c.submitting = false;
            var res = resp.data.result;
            if (res && res.ok) {
                applySession(res.session, false);
                return;
            }
            if (isTimeUp) {
                resync();
            } else {
                c.errorText = (res && res.message) || 'Submit failed. Please try again.';
            }
        }, function() {
            c.submitting = false;
            c.errorText = 'Could not reach the server. Check your connection; your answers are still here.';
            if (isTimeUp) $timeout(function() { timeUpSent = false; }, 5000);
        });
    }

    /** Re-reads the session from the server, e.g. if the browser's countdown ran ahead. */
    function resync() {
        c.server.get({ action: 'refresh' }).then(function(resp) {
            var res = resp.data.result;
            if (res && res.ok) applySession(res.session, false);
            $timeout(function() { timeUpSent = false; }, 3000);
        });
    }

    /* ---------------- cleanup ---------------- */

    $scope.$on('$destroy', function() {
        if (tickTimer) $interval.cancel(tickTimer);
        if (autosaveLoop) $interval.cancel(autosaveLoop);
        if (waitPoll) $interval.cancel(waitPoll);
        if (statusPoll) $interval.cancel(statusPoll);
        cancelAutosave();
    });
};

sp_widget.css:
/* Fun on PDI - Crossword widget */
.fun-xw {
  /* BCE Global Tech palette */
  --brand: #00549a;      /* primary blue: lines, buttons, timer */
  --brand-dark: #003778; /* clue bar, headings rule */
  --ink: #1b2733;        /* text */
  --paper: #ffffff;      /* letter squares */
  --block: #e9eff6;      /* unused squares, light blue-grey */
  --word: #d3e5f7;       /* selected word */
  --cursor: #00549a;     /* selected square */
  --accent: #00549a;
  --amber: #a86400;
  --red: #b3261e;
  --muted: #5b6878;
  --surface: #f2f6fa;
  /* board defaults; the client controller overrides them on the board in exact px */
  --cols: 15;
  --cell: 35px;
  --line: 1px;
  --pad: 10px;
  --pad-end: 11px;
  --num: 9.5px;
  --letter: 19.6px;

  max-width: 980px;
  margin: 0 auto;
  padding: 16px 12px 40px;
  color: var(--ink);
}

/* ---------- header ---------- */
.fun-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 16px;
  flex-wrap: wrap;
  padding-bottom: 12px;
  border-bottom: 3px solid var(--brand);
  margin-bottom: 16px;
}
.fun-title h1 {
  margin: 0;
  font-size: 28px;
  font-weight: 800;
  line-height: 1.1;
}
.fun-title p {
  margin: 4px 0 0;
  color: var(--brand);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.02em;
}
.fun-status {
  display: flex;
  align-items: center;
  gap: 12px;
}
.fun-save {
  font-size: 13px;
  color: var(--muted);
}
.fun-timer {
  font-variant-numeric: tabular-nums;
  font-size: 26px;
  font-weight: 800;
  padding: 4px 14px;
  border: 2px solid var(--accent);
  border-radius: 6px;
  color: var(--accent);
  min-width: 96px;
  text-align: center;
}
.fun-timer.is-low { color: var(--amber); border-color: var(--amber); }
.fun-timer.is-critical { color: #fff; background: var(--red); border-color: var(--red); }
.fun-timer.is-done { color: var(--muted); border-color: #c5ccd3; }

/* ---------- messages ---------- */
.fun-result,
.fun-error {
  padding: 14px 16px;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 16px;
}
.fun-result.is-ok { background: #e3f4ea; color: #0f5a37; border: 1px solid #9fd3b5; }
.fun-result.is-warn { background: #fff3dc; color: #7a4a00; border: 1px solid #f0c977; }
.fun-error { background: #fbe9e8; color: var(--red); border: 1px solid #efb3ae; font-weight: 600; }

.fun-empty {
  max-width: 520px;
  margin: 60px auto;
  padding: 24px;
  border: 2px solid var(--brand);
  border-radius: 8px;
}
.fun-empty h2 { margin-top: 0; font-size: 20px; }

/* ---------- current clue bar ---------- */
/* the selected clue stays pinned to the top of the screen while scrolling */
.fun-current {
  position: sticky;
  top: 0;
  z-index: 10;
  box-shadow: 0 4px 10px rgba(0, 55, 120, 0.25);
  display: flex;
  gap: 10px;
  align-items: baseline;
  background: var(--brand-dark);
  color: #fff;
  padding: 10px 14px;
  border-radius: 6px;
  margin: 0 auto 12px;
  font-size: 15px;
}
.fun-current-ref { font-weight: 800; white-space: nowrap; color: #9fd0ff; }

/* ---------- grid ---------- */
.fun-board-wrap {
  display: flex;
  justify-content: center;
  overflow-x: auto;
  padding: 2px;
}
.fun-board {
  position: relative;
  z-index: 0;              /* keeps the square frames below the pinned clue bar */
  display: grid;
  grid-template-columns: repeat(var(--cols, 15), var(--cell, 35px));
  grid-auto-rows: var(--cell, 35px);
  background: #e9eff6;
  border-radius: 8px;
  padding: var(--pad, 10px) var(--pad-end, 11px) var(--pad-end, 11px) var(--pad, 10px);
}
.fun-cell {
  position: relative;
  background: var(--block);
}
/* letter squares: each square fills its grid slot exactly. Its border is a separate
   frame (::after) that reaches one line past the right and bottom edges and is drawn
   above every square, so neighbouring squares share one line in the same place.
   All sizes are plain values set by the client controller (no calc), whole screen pixels. */
.fun-cell:not(.is-block) {
  background: var(--paper);
}
.fun-cell:not(.is-block)::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: var(--overlap, -1px);
  bottom: var(--overlap, -1px);
  border: var(--line, 1px) solid var(--brand);
  pointer-events: none;
  z-index: 1;
}
.fun-cell.in-word { background: var(--word); }
.fun-cell.is-active { background: var(--cursor); }
.fun-cell.is-active .fun-input,
.fun-cell.is-active .fun-num { color: #fff; }

.fun-num {
  position: absolute;
  z-index: 2;
  top: 1px;
  left: 2px;
  font-size: var(--num, 9px);
  line-height: 1;
  font-weight: 700;
  pointer-events: none;
}
.fun-input {
  width: 100%;
  height: 100%;
  border: 0;
  padding: 0;
  margin: 0;
  background: transparent;
  text-align: center;
  text-transform: uppercase;
  font-size: var(--letter, 20px);
  font-weight: 800;
  color: var(--ink);
  caret-color: transparent;
  cursor: pointer;
  border-radius: 0;
}
.fun-input:focus { outline: none; }
.fun-input:disabled { cursor: default; color: var(--ink); opacity: 1; -webkit-text-fill-color: var(--ink); }

/* ---------- actions ---------- */
.fun-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  margin: 18px 0 8px;
}
.fun-progress { margin: 0; font-weight: 700; }
.fun-hint { margin: 0; color: var(--muted); font-size: 14px; }
.fun-info {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-radius: 6px;
  background: #e6f0fa;
  border: 1px solid #b7d3ee;
  color: var(--brand-dark);
  font-size: 14px;
  font-weight: 600;
}
.fun-info-icon {
  flex: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--brand);
  color: #fff;
  font: italic 700 13px/20px Georgia, "Times New Roman", serif;
  text-align: center;
}

.fun-submit,
.fun-secondary {
  font-size: 16px;
  font-weight: 700;
  padding: 10px 22px;
  border-radius: 6px;
  cursor: pointer;
}
.fun-submit {
  background: var(--accent);
  color: #fff;
  border: 2px solid var(--accent);
}
.fun-submit:hover { background: var(--brand-dark); border-color: var(--brand-dark); }
.fun-submit[disabled] { opacity: 0.6; cursor: default; }
.fun-secondary {
  background: #fff;
  color: var(--ink);
  border: 2px solid #c5ccd3;
}
.fun-submit:focus-visible,
.fun-secondary:focus-visible,
.fun-clues li:focus-visible {
  outline: 3px solid #9fd0ff;
  outline-offset: 2px;
}

/* ---------- clues ---------- */
.fun-howto {
  margin: 0 0 16px;
  background: var(--surface);
  border-left: 4px solid var(--brand);
  border-radius: 4px;
}
.fun-howto-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: none;
  border: 0;
  padding: 12px 16px;
  font-size: 16px;
  font-weight: 800;
  color: var(--brand-dark);
  cursor: pointer;
  text-align: left;
}
.fun-howto-toggle:focus-visible { outline: 3px solid #9fd0ff; outline-offset: -3px; }
.fun-chevron {
  width: 10px;
  height: 10px;
  border-right: 2px solid var(--brand);
  border-bottom: 2px solid var(--brand);
  transform: rotate(45deg);
  margin-top: -4px;
  transition: transform 0.2s;
}
.fun-chevron.is-open { transform: rotate(-135deg); margin-top: 4px; }
@media (prefers-reduced-motion: reduce) { .fun-chevron { transition: none; } }
.fun-howto-list { margin: 0; padding: 0 16px 14px 36px; }
.fun-howto-list li { margin-bottom: 8px; line-height: 1.45; }
.fun-howto-list li:last-child { margin-bottom: 0; }
.fun-howto-list strong { color: var(--brand-dark); }
.fun-clues {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 3px solid var(--brand);
}
.fun-clue-col h2 {
  font-size: 18px;
  font-weight: 800;
  margin: 0 0 8px;
}
.fun-clue-col ol { list-style: none; margin: 0; padding: 0; }
.fun-clue-col li {
  display: flex;
  gap: 10px;
  padding: 6px 8px;
  border-radius: 4px;
  cursor: pointer;
  line-height: 1.4;
}
.fun-clue-col li:hover { background: var(--surface); }
.fun-clue-col li.is-current { background: var(--word); }
.fun-clue-col li.is-filled { color: var(--muted); }
.fun-clue-num { font-weight: 800; min-width: 22px; color: var(--brand); }

.fun-keys {
  margin-top: 16px;
  font-size: 13px;
  color: var(--muted);
  text-align: center;
}

/* ---------- locked after submit ---------- */
.fun-xw.is-locked .fun-cell.in-word,
.fun-xw.is-locked .fun-cell.is-active { background: var(--paper); }
.fun-xw.is-locked .fun-clue-col li { cursor: default; }

/* ---------- confirmation ---------- */
.fun-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1050;
  background: rgba(0, 55, 120, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.fun-modal {
  background: #fff;
  border-radius: 8px;
  padding: 22px 24px;
  max-width: 420px;
  width: 100%;
  border-top: 6px solid var(--accent);
}
.fun-modal h2 { margin: 0 0 8px; font-size: 20px; font-weight: 800; }
.fun-modal p { margin: 0 0 18px; color: var(--muted); }
.fun-modal-actions { display: flex; justify-content: flex-end; gap: 10px; flex-wrap: wrap; }

/* ---------- small screens ---------- */
@media (max-width: 640px) {
  .fun-title h1 { font-size: 22px; }
  .fun-timer { font-size: 20px; min-width: 80px; }
  .fun-clues { grid-template-columns: 1fr; }
  .fun-keys { display: none; }
}

/* ---------- first-login team setup ---------- */
.fun-reg-backdrop { background: rgba(0, 55, 120, 0.12); }
.fun-reg { max-width: 480px; border-top-color: var(--brand); }
.fun-reg p { color: var(--ink); }
.fun-label {
  display: block;
  font-size: 14px;
  font-weight: 700;
  margin: 14px 0 6px;
  padding: 0;
  border: 0;
}
.fun-field {
  width: 100%;
  font-size: 16px;
  padding: 8px 10px;
  border: 1px solid #b9c5d2;
  border-radius: 4px;
  color: var(--ink);
}
.fun-field:focus { outline: 2px solid #9fd0ff; border-color: var(--brand); }
.fun-members { border: 0; padding: 0; margin: 0; min-width: 0; }
.fun-member { display: flex; gap: 8px; align-items: center; margin-bottom: 8px; }
.fun-link {
  background: none;
  border: 0;
  padding: 4px 2px;
  color: var(--brand);
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}
.fun-link:hover { text-decoration: underline; }
.fun-reg-note { font-size: 14px; color: var(--muted) !important; margin: 14px 0 12px; }
.fun-reg .fun-error { font-size: 14px; }

/* ---------- waiting for the game to start ---------- */
.fun-wait {
  display: flex;
  justify-content: center;
  padding: 60px 0;
}
.fun-wait-card {
  max-width: 520px;
  text-align: center;
  padding: 32px 28px;
  border-radius: 8px;
  background: var(--surface);
  border-top: 6px solid var(--brand);
}
.fun-wait-card h2 { margin: 16px 0 8px; font-size: 24px; font-weight: 800; color: var(--brand-dark); }
.fun-wait-card p { margin: 0 0 8px; font-size: 16px; }
.fun-wait-note { color: var(--muted); font-size: 14px !important; }
.fun-wait-dots { display: inline-flex; gap: 8px; }
.fun-wait-dots span {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--brand);
  animation: fun-pulse 1.2s infinite ease-in-out;
}
.fun-wait-dots span:nth-child(2) { animation-delay: 0.2s; }
.fun-wait-dots span:nth-child(3) { animation-delay: 0.4s; }
@keyframes fun-pulse {
  0%, 80%, 100% { opacity: 0.25; transform: scale(0.8); }
  40% { opacity: 1; transform: scale(1); }
}
@media (prefers-reduced-motion: reduce) {
  .fun-wait-dots span { animation: none; opacity: 0.7; }
}

sp_widget.script:
(function() {
    /* Fun on PDI - Crossword widget (server script)
     * All game logic lives in FunCrosswordService. Answers never reach the browser.
     *
     * input.action:
     *   'save'    -> autosave the grid
     *   'submit'  -> final submit (input.isTimeUp = true when the countdown hit 0)
     *   'refresh' -> reload the puzzle and session (re-sync the timer)
     *   'register'-> first login: save team name and members
     *   (none)    -> first page load
     */
    // Everyone signs in at /fun. Game masters (and admins) are sent on to the console;
    // players stay here and get the crossword.
    if (!input && gs.hasRole('x_1802710_fun_on_0.game_master')) {
        data.redirectTo = '/fun_gm?id=fun_console';
        return;
    }

    var svc = new FunCrosswordService();
    var userId = gs.getUserID();

    if (input && input.action) {
        if (input.action == 'save') {
            data.result = svc.saveProgress(userId, input.cells);
        } else if (input.action == 'submit') {
            data.result = svc.submit(userId, input.cells, input.isTimeUp === true);
        } else if (input.action == 'register') {
            data.result = svc.registerTeam(userId, input.teamName, input.members);
        } else if (input.action == 'refresh') {
            data.result = svc.getPuzzleForUser(userId);
        } else {
            data.result = { ok: false, message: 'Unknown action.' };
        }
        return;
    }

    data.game = svc.getPuzzleForUser(userId);
})();
